class Order
  attr_reader :id, :total_cents
  def initialize(id, credit_limit_cents)
    @id, @credit_limit_cents = id, credit_limit_cents
    @line_items, @total_cents = [], 0
  end
  def add_line(line)
    raise CreditLimitExceeded if @total_cents + line.amount_cents > @credit_limit_cents
    @line_items << line
    @total_cents += line.amount_cents
  end
  def line_items = @line_items.freeze   # never the mutable array
end
